const { pointInPolygon } = require('./r4_geom.js');

// Test cases
console.log("Testing pointInPolygon function...");

// Test 1: Point inside a triangle
const triangle = [
    {x: 0, y: 0},
    {x: 4, y: 0},
    {x: 2, y: 4}
];

